/* Текущий язык + функция перевода с подстановкой {переменных} */
let LANG = (() => {
  try { return localStorage.getItem('kb_lang') || 'ru'; } catch (e) { return 'ru'; }
})();

function setLang(code) {
  if (!I18N[code]) return;
  LANG = code;
  try { localStorage.setItem('kb_lang', code); } catch (e) {}
}

function t(key, vars) {
  let s = (I18N[LANG] && I18N[LANG][key]) ?? I18N.ru[key] ?? key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}

if (typeof module !== 'undefined') module.exports = { I18N, LANGS, t, setLang, get LANG() { return LANG; } };
